UPDATE posts SET content = replace(content, 'Check the Core Web Vitals report in Search Console for real-user data, and PageSpeed Insights for individual URLs.', 'Check the Core Web Vitals report in Search Console for real-user data, and PageSpeed Insights for individual URLs. If the acronyms are new, start with <a href="https://blog.scaryspiderseo.com/web-performance/core-web-vitals-explained">what LCP, INP and CLS measure</a>.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'technical-seo-audit-checklist' AND instr(content, 'Check the Core Web Vitals report in Search Console for real-user data, and PageSpeed Insights for individual URLs.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/web-performance/core-web-vitals-explained"') = 0;
