UPDATE posts SET content = replace(content, 'Fix: compare the canonical in the raw HTML with the one in the rendered page. They should match.', 'Fix: compare the canonical in the raw HTML with the one in the rendered page. They should match. Our guide to <a href="https://blog.scaryspiderseo.com/web-performance/javascript-seo-rendering">JavaScript rendering and SEO</a> shows how to compare the two.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'canonical-tags-explained' AND instr(content, 'Fix: compare the canonical in the raw HTML with the one in the rendered page. They should match.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/web-performance/javascript-seo-rendering"') = 0;
