UPDATE posts SET content = replace(content, 'Is the interface easy to navigate on a phone (Mobile-friendliness)?', 'Is the interface easy to navigate on a phone (Mobile-friendliness)? Google mainly uses the mobile version of your site for indexing, so work through this <a href="https://blog.scaryspiderseo.com/web-performance/mobile-first-indexing-checklist">mobile-first indexing checklist</a>.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'dont-let-your-website-turn-invisible-a-beginner-guide' AND instr(content, 'Is the interface easy to navigate on a phone (Mobile-friendliness)?') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/web-performance/mobile-first-indexing-checklist"') = 0;
UPDATE posts SET content = replace(content, 'Missing or out-of-order headings make that much harder.', 'Missing or out-of-order headings make that much harder. It is one of several places where <a href="https://blog.scaryspiderseo.com/accessibility/accessibility-and-seo">accessibility and SEO overlap</a>.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'heading-tags-seo' AND instr(content, 'Missing or out-of-order headings make that much harder.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/accessibility/accessibility-and-seo"') = 0;
